//! Interop: certificates generated by rcgen (on ring) verify here; certificates generated here
//! verify with rustls-webpki; keys move between the two.

use akio_crypto::pkey::PrivateKey;
use akio_x509::{Certificate, CertificateParams, KeyUsage, RootStore, Verifier, ext};
use rustls_pki_types::{CertificateDer, ServerName as PkiServerName, UnixTime};

fn rcgen_chain(alg: &'static rcgen::SignatureAlgorithm) -> (String, String, rcgen::KeyPair) {
    let ca_key = rcgen::KeyPair::generate_for(alg).unwrap();
    let mut ca = rcgen::CertificateParams::new(Vec::<String>::new()).unwrap();
    ca.is_ca = rcgen::IsCa::Ca(rcgen::BasicConstraints::Unconstrained);
    ca.distinguished_name
        .push(rcgen::DnType::CommonName, "rcgen CA");
    ca.key_usages = vec![
        rcgen::KeyUsagePurpose::KeyCertSign,
        rcgen::KeyUsagePurpose::CrlSign,
    ];
    let ca_cert = ca.self_signed(&ca_key).unwrap();
    let leaf_key = rcgen::KeyPair::generate_for(alg).unwrap();
    let mut leaf =
        rcgen::CertificateParams::new(vec!["rcgen.test".to_string(), "127.0.0.1".to_string()])
            .unwrap();
    leaf.extended_key_usages = vec![rcgen::ExtendedKeyUsagePurpose::ServerAuth];
    let leaf_cert = leaf.signed_by(&leaf_key, &ca_cert, &ca_key).unwrap();
    (ca_cert.pem(), leaf_cert.pem(), leaf_key)
}

#[test]
fn rcgen_certificates_verify_here() {
    for alg in [
        &rcgen::PKCS_ECDSA_P256_SHA256,
        &rcgen::PKCS_ECDSA_P384_SHA384,
        &rcgen::PKCS_ED25519,
    ] {
        let (ca, leaf, leaf_key) = rcgen_chain(alg);
        let mut store = RootStore::new();
        store.add_pem(ca.as_bytes()).unwrap();
        let leaf = Certificate::from_pem(leaf.as_bytes()).unwrap().remove(0);
        let v = Verifier::new(&store);
        v.verify_server(&leaf, &[], "rcgen.test").unwrap();
        v.verify_server(&leaf, &[], "127.0.0.1").unwrap();
        assert!(v.verify_server(&leaf, &[], "other.test").is_err());
        // rcgen's PKCS#8 key loads, and its public key is the certificate's.
        let k = PrivateKey::from_pem(leaf_key.serialize_pem().as_bytes()).unwrap();
        assert_eq!(k.public_key(), leaf.public_key().unwrap());
    }
}

#[test]
fn our_certificates_verify_with_webpki() {
    for ca_key in [
        PrivateKey::P256(akio_crypto::p256::SecretKey::generate().unwrap()),
        PrivateKey::P384(akio_crypto::p384::SecretKey::generate().unwrap()),
        PrivateKey::Ed25519(akio_crypto::ed25519::SigningKey::generate().unwrap()),
    ] {
        let ca = CertificateParams::ca("akio CA")
            .self_signed(&ca_key)
            .unwrap();
        let leaf_key = PrivateKey::P256(akio_crypto::p256::SecretKey::generate().unwrap());
        let mut p = CertificateParams::new(["akio.test", "*.akio.test", "10.0.0.1"]);
        p.extended_key_usage = vec![ext::SERVER_AUTH.to_vec(), ext::CLIENT_AUTH.to_vec()];
        p.key_usage = Some(KeyUsage::DIGITAL_SIGNATURE);
        let leaf = p.signed_by(&leaf_key.public_key(), &ca, &ca_key).unwrap();

        let ca_der = CertificateDer::from(ca.as_der().to_vec());
        let anchor = webpki::anchor_from_trusted_cert(&ca_der).unwrap();
        let leaf_der = CertificateDer::from(leaf.as_der().to_vec());
        let ee = webpki::EndEntityCert::try_from(&leaf_der).unwrap();
        let now = UnixTime::now();
        ee.verify_for_usage(
            webpki::ALL_VERIFICATION_ALGS,
            &[anchor],
            &[],
            now,
            webpki::KeyUsage::server_auth(),
            None,
            None,
        )
        .unwrap();
        for name in ["akio.test", "a.akio.test", "10.0.0.1"] {
            ee.verify_is_valid_for_subject_name(&PkiServerName::try_from(name).unwrap())
                .unwrap();
        }
        assert!(
            ee.verify_is_valid_for_subject_name(&PkiServerName::try_from("x.y.akio.test").unwrap())
                .is_err()
        );

        // rcgen loads our PKCS#8 keys.
        let pem = leaf_key.to_pkcs8_pem();
        let rk = rcgen::KeyPair::from_pem(&pem).unwrap();
        assert_eq!(rk.public_key_der(), leaf_key.public_key().to_spki_der());
    }
}

#[test]
fn simple_self_signed_like_rcgen() {
    let (cert, key) = akio_x509::generate_simple_self_signed(["localhost"]).unwrap();
    let der = CertificateDer::from(cert.as_der().to_vec());
    let anchor = webpki::anchor_from_trusted_cert(&der).unwrap();
    let ee = webpki::EndEntityCert::try_from(&der).unwrap();
    ee.verify_for_usage(
        webpki::ALL_VERIFICATION_ALGS,
        &[anchor],
        &[],
        UnixTime::now(),
        webpki::KeyUsage::server_auth(),
        None,
        None,
    )
    .unwrap();
    ee.verify_is_valid_for_subject_name(&PkiServerName::try_from("localhost").unwrap())
        .unwrap();
    let _ = key;
}
